    $scope.GetVisitReasonsNew = function (id) {
        id = id || 0;
        var Org_id = 0;
        if (id == 0) {
            Org_id = $scope.HospitalId;
        } else {
            Org_id = id;
        }
        var obj = {
            "OrganizationId": Org_id,
            "UserId": doctorinfo.doctorid,
            "VisitTypeId": 0,
            "visitReasonSearch": "",
            "PageNumber": 1,
            "PageSize": 1000,
            "IsFrequent": "N"
        };
        eHnotePatientVisitReasonServices.GetOrganizationActiveAppointmentVisitReasonsById(obj).then(function (resp) {

            if (resp.data !== undefined) {
                if (resp.data.rows.length > 0) {
                    $scope.Visitreasons = resp.data.rows;
                    $scope.VisitReasonsWiseApptCount = resp.data.rows;
                    $scope.CalVisitreasons = resp.data.rows || [];
                    angular.forEach($scope.Visitreasons, function (item) {
                        item.isChecked = true;
                    });
                    $scope.VisitreasonsforPrint = angular.copy($scope.Visitreasons) || [];
                    angular.forEach($scope.VisitreasonsforPrint, function (item) {
                        item.isChecked = false;
                    });
                }
                angular.forEach($scope.VisitReasonsWiseApptCount, function (item) {
                    item.isChecked = true;
                });
                $scope.VisitReasonsWiseApptCountForPrint = angular.copy($scope.VisitReasonsWiseApptCount) || [];
                angular.forEach($scope.VisitReasonsWiseApptCountForPrint, function (item) {
                    item.isChecked = false;
                });
                $scope.SelectedApptTabFreeze.SelectedVisitreasons = $scope.SelectedApptTabFreeze.SelectedVisitreasons || [];
                $scope.Visitreasons = $scope.Visitreasons || [];
                if ($scope.Visitreasons.length > 0 && $scope.SelectedApptTabFreeze.SelectedVisitreasons.length > 0) {
                    angular.forEach($scope.Visitreasons, function (Mitem) {
                        Mitem.isChecked = false;
                    });
                    angular.forEach($scope.SelectedApptTabFreeze.SelectedVisitreasons, function (Selecteditem) {
                        angular.forEach($scope.Visitreasons, function (Mainitem) {
                            if (Selecteditem.ReasonId == Mainitem.ReasonId) {
                                Mainitem.isChecked = true;
                            }
                        });
                    });
                    var checkedArray1 = _.where($scope.Visitreasons, { isChecked: true });
                    $scope.AllDoctorsObj.AllVisitReasonsCheck = checkedArray1.length > 0 && $scope.Visitreasons.length === checkedArray1.length ? true : false;
                    if (checkedArray1.length == 0) {
                        $scope.selectedVisitReason = 'All Visit Reasons';
                    } else {
                        if (checkedArray1.length === 1) {
                            $scope.selectedVisitReason = checkedArray1[0].Reason;
                        } else {
                            $scope.selectedVisitReason = 'All Visit Reasons';
                        }
                    }
                }
            }
        });
    };

