    $scope.getdoctorsandvisitreasonsdata = function (pagetype) {
        $scope.Visitreasons = [];
        var pagetype = pagetype || "";
        var locationIds = $scope.AppListdoctoraddress.filter(pitem => pitem.IsChecked && pitem.ClinicId !== 0)
            .map(pitem => pitem.ClinicId)
            .join(",");
        var usersReqParams = {
            "BranchId": locationIds,
        }
        var visitreasonParams = {
            "OrganizationId": locationIds,
            "VisitTypeId": 0,
            "SearchText": "",
        };

        $q.all([
            //eHnotePatientVisitReasonServices.GetOrganizationActiveAppointmentVisitReasonsById(visitreasonParams),
            eHnotePatientVisitReasonServices.GetOrganizationActiveAndInActiveApptVisitReasons(visitreasonParams),
            eHnoteMainAppointmentService.getAllUsersByDepartmentIdNew(usersReqParams),
        ]).then(function (resp) {
            console.log(resp);
            resp[0].data.rows = resp[0].data.rows || [];
            resp[1].data.rows = resp[1].data.rows || [];

            $scope.MultiselectDoctorlist = [];
            $scope.selectedDoctors = "Select Doctor";
            $scope.AllDoctorsObj.AllDoctorCheck = false;

            if (resp[0].data !== undefined) {
                if (resp[0].data.rows.length > 0) {

                    $scope.Visitreasons = resp[0].data.rows;
                    $scope.VisitReasonsWiseApptCount = resp[0].data.rows;


                    $scope.GetVisitReasonsArray = [];
                    $scope.GetVisitReasonsArray = $filter("filter")(resp[0].data.rows, function (kitem) {
                        return kitem.ActiveIND == "Y";
                    });

                    $scope.CalVisitreasons = $filter("filter")(resp[0].data.rows, function (kitem) { return kitem.ActiveInd == "Y"; });
                    angular.forEach($scope.Visitreasons, function (item) {
                        item.isChecked = true;
                    });
                    $scope.VisitreasonsforPrint = angular.copy($scope.Visitreasons) || [];
                    angular.forEach($scope.VisitreasonsforPrint, function (item) {
                        item.isChecked = false;
                    });
                }
                angular.forEach($scope.VisitReasonsWiseApptCount, function (item) {
                    item.isChecked = true;
                });
                $scope.VisitReasonsWiseApptCountForPrint = angular.copy($scope.VisitReasonsWiseApptCount) || [];
                angular.forEach($scope.VisitReasonsWiseApptCountForPrint, function (item) {
                    item.isChecked = false;
                });
                $scope.SelectedApptTabFreeze.SelectedVisitreasons = $scope.SelectedApptTabFreeze.SelectedVisitreasons || [];
                $scope.Visitreasons = $scope.Visitreasons || [];
                if ($scope.Visitreasons.length > 0 && $scope.SelectedApptTabFreeze.SelectedVisitreasons.length > 0) {
                    angular.forEach($scope.Visitreasons, function (Mitem) {
                        Mitem.isChecked = false;
                    });
                    angular.forEach($scope.SelectedApptTabFreeze.SelectedVisitreasons, function (Selecteditem) {
                        angular.forEach($scope.Visitreasons, function (Mainitem) {
                            if (Selecteditem.ReasonId == Mainitem.ReasonId) {
                                Mainitem.isChecked = true;
                            }
                        });
                    });
                    var checkedArray1 = _.where($scope.Visitreasons, { isChecked: true });
                    $scope.AllDoctorsObj.AllVisitReasonsCheck = checkedArray1.length > 0 && $scope.Visitreasons.length === checkedArray1.length ? true : false;
                    if (checkedArray1.length == 0) {
                        $scope.selectedVisitReason = 'All Visit Reasons';
                    } else {
                        if (checkedArray1.length === 1) {
                            $scope.selectedVisitReason = checkedArray1[0].Reason;
                        } else {
                            $scope.selectedVisitReason = 'All Visit Reasons';
                        }
                    }
                }
            }

            if (resp[1].data.rows.length > 0) {
                $scope.getDoctorsbySubSpecializations(resp[1].data.rows, pagetype);
            }
        }, function (err) {
            console.log(err);
        });
    }

    function InitializeBranches(data, pagetype) {
        var clinicAddress = eHnoteUserAppointmentDataService.RestructureNewBranches($scope.UserAccessRights.AllAccessRights.APPListAllBranchesAppointments, data, doctorInfo) || [];
        var EmptyClinicObj = {
            "ClinicName": "All Locations",
            "ClinicId": 0,
            "BranchName": "All Locations",
            "BranchId": 0,
            "SubOrganizationId": 0,
            "Address1": "",
            "Address2": "",
            "Location": "",
            "StateId": "",
            "PinCode": "",
            "CountryId": "",
            "CityId": "",
            "DistrictRegion": "",
            "Latitude": "",
            "Longitude": "",
            "BranchEmail": "",
            "CountryCode": "",
            "mobilenum": "",
            "Active": "Y",
            "Doctors": [],
            "CommunicationCountryCode": "",
            "CommunicationMobileNo": "",
            "IsChecked":false
        };
        clinicAddress.unshift(EmptyClinicObj);
        $scope.BranchesListArray = clinicAddress;

        $scope.AppListdoctoraddress = clinicAddress;
        $scope.ApptBranchLocations = clinicAddress;
        $scope.AppListselectedclinic = $scope.AppListdoctoraddress[0];

        var RoleID = $scope.userLoginDetails.RoleID;

        $scope.clinicDoctorList = [];

        $scope.defaultbranch = $filter("filter")($scope.AppListdoctoraddress, function (item) {
            return item.BranchId === doctorInfo.doctordata.UserAddress[0].ClinicId;
        });

        $scope.selectedBranch = "";
        $scope.selectedBranch = $scope.defaultbranch[0];
        $scope.AppListselectedclinic = $scope.defaultbranch[0];
        if (RoleID === 2 || RoleID === 10 || RoleID === 11 || RoleID === 58) {
            angular.forEach($scope.AppListdoctoraddress, function (item, index) {
                if (item.ClinicName !== "All Locations") {
                    if (item.ClinicId === $scope.hospid) {
                        $scope.selectedBranch = item;
                        $scope.AppListselectedclinic = item;
                        eHnoteMasterDataService.addSelectedHospitalinAppList(item);
                    }
                }
            });
        }



        var freeezedCookeData = eHnoteMasterDataService.getSelectedCRMApptTabFreeze();
        freeezedCookeData = freeezedCookeData || "";

        if (freeezedCookeData === "") {
            if ($scope.selectedBranch.BranchId === 0) {
                if (doctorInfo.doctordata.UserAddress[0].SubOrganizationId) {
                    $scope.selectedBranch.SubOrganizationId = doctorInfo.doctordata.UserAddress[0].SubOrganizationId;
                    $scope.AppListselectedclinic.SubOrganizationId = doctorInfo.doctordata.UserAddress[0].SubOrganizationId;
                }

                angular.forEach($scope.AppListdoctoraddress, function (mitem) {
                    mitem.IsChecked = true;
                });
                $scope.LocationTypeObj.SelectLocationString = "All Locations";
            }
            else {
                angular.forEach($scope.AppListdoctoraddress, function (mitem) {
                    if (mitem.ClinicId === $scope.selectedBranch.BranchId) {
                        mitem.IsChecked = true;
                        $scope.LocationTypeObj.SelectLocationString = mitem.ClinicName;
                    }
                });
            }
        } else {
            if (freeezedCookeData.SelectedBranchesList.length > 0) {
                $scope.AppListdoctoraddress.forEach(mitem => {
                    mitem.IsChecked = freeezedCookeData.SelectedBranchesList.some(sitem => mitem.ClinicId === sitem.ClinicId);
                });
                $scope.LocationTypeObj.SelectLocationString = "Selected";
            }
            else {
                if ($scope.selectedBranch.BranchId === 0) {
                    if (doctorInfo.doctordata.UserAddress[0].SubOrganizationId) {
                        $scope.selectedBranch.SubOrganizationId = doctorInfo.doctordata.UserAddress[0].SubOrganizationId;
                        $scope.AppListselectedclinic.SubOrganizationId = doctorInfo.doctordata.UserAddress[0].SubOrganizationId;
                    }

                    angular.forEach($scope.AppListdoctoraddress, function (mitem) {
                        mitem.IsChecked = true;
                    });
                    $scope.LocationTypeObj.SelectLocationString = "All Locations";
                }
                else {
                    angular.forEach($scope.AppListdoctoraddress, function (mitem) {
                        if (mitem.ClinicId === $scope.selectedBranch.BranchId) {
                            mitem.IsChecked = true;
                            $scope.LocationTypeObj.SelectLocationString = mitem.ClinicName;
                        }
                    });
                }
            }

            let selectedBranches = $scope.AppListdoctoraddress.filter(bitem => bitem.ClinicId !== 0 && bitem.IsChecked);
            if (selectedBranches.length === 1) {
                $scope.AppListselectedclinic = angular.copy(selectedBranches[0]);
            }
        }

       

        eHnotePatientAddressDataServices.getAppointmentTypes(onTypesSuccess, onTypesFailed);
        function onTypesSuccess(data) {
            $scope.appointmentTypes = [];
            $scope.appointmentTypes = data;

            if ($scope.userLoginDetails.RoleID == 1 || $scope.userLoginDetails.RoleID == 43) {
                angular.forEach($scope.appointmentTypes, function (mitem) {
                    mitem.isChecked = false;
                    if ($scope.userLoginDetails.RoleID == 1 || $scope.userLoginDetails.RoleID == 43) {
                        if (mitem.Id == 1 || mitem.Id == 2 || mitem.Id == 3 || mitem.Id == 4) {
                            mitem.isChecked = true;
                        }
                    }
                    //if ($scope.userLoginDetails.RoleID == 10) {
                    //    if (mitem.Id == 5) {
                    //        mitem.isChecked = true;
                    //    }
                    //}
                    if ($scope.userLoginDetails.RoleID == 18) {
                        // if (mitem.Id == 6) {
                        mitem.isChecked = true;
                        // }
                    }
                });
                $scope.AllDoctorsObj.AllAppointmentTypeStatusCheck = true;
                $scope.selectVisitType = 'All Visit Types';
                if ($scope.userLoginDetails.RoleID == 1) {
                    $scope.selectVisitType = "All";
                }
            }
            else if ($scope.userLoginDetails.RoleID === 62 || $scope.userLoginDetails.RoleID === 63) {
                angular.forEach($scope.appointmentTypes, function (mitem) {
                    mitem.isChecked = false;
                    if (mitem.Id !== 4 && mitem.Id !== 6) {
                        mitem.isChecked = true;
                    }
                });
                $scope.AllDoctorsObj.AllAppointmentTypeStatusCheck = false;

            }
            else if ($scope.userLoginDetails.RoleID === 68) {
                angular.forEach($scope.appointmentTypes, function (mitem) {
                    mitem.isChecked = false;
                    if (mitem.Id !== 5 && mitem.Id !== 6) {
                        mitem.isChecked = true;
                    }
                });
                $scope.AllDoctorsObj.AllAppointmentTypeStatusCheck = false;
            }
            else if ($scope.userLoginDetails.RoleID === 66 || $scope.userLoginDetails.RoleID === 67) {
                angular.forEach($scope.appointmentTypes, function (mitem) {
                    mitem.isChecked = false;
                    if (mitem.Id === 4 || mitem.Id === 6) {
                        mitem.isChecked = true;
                    }
                });
                $scope.AllDoctorsObj.AllAppointmentTypeStatusCheck = false;

            }
            else {
                angular.forEach($scope.appointmentTypes, function (mitem) {
                    mitem.isChecked = true;
                });
                $scope.AllDoctorsObj.AllAppointmentTypeStatusCheck = true;
                $scope.selectVisitType = "All";
            }

            $scope.SelectedApptTabFreeze.SelectedappointmentTypes = $scope.SelectedApptTabFreeze.SelectedappointmentTypes || [];
            $scope.appointmentTypes = $scope.appointmentTypes || [];
            if ($scope.appointmentTypes.length > 0 && $scope.SelectedApptTabFreeze.SelectedappointmentTypes.length > 0) {
                angular.forEach($scope.appointmentTypes, function (Mitem) {
                    Mitem.isChecked = false;
                });
                angular.forEach($scope.SelectedApptTabFreeze.SelectedappointmentTypes, function (Selecteditem) {
                    angular.forEach($scope.appointmentTypes, function (Mainitem) {
                        if (Selecteditem.Id == Mainitem.Id) {
                            Mainitem.isChecked = true;
                        }
                    });
                });
                var checkedArray = _.where($scope.appointmentTypes, { isChecked: true });
                $scope.AllDoctorsObj.AllAppointmentTypeStatusCheck = checkedArray.length > 0 && $scope.appointmentTypes.length === checkedArray.length ? true : false;


                let checkedBookingTypesArray = [];
                if ($scope.BookingTypesArray.length > 0) {
                    checkedBookingTypesArray = _.where($scope.BookingTypesArray, { IsChecked: true });
                }

                if (checkedArray.length == 0) {
                    $scope.selectVisitType = "All Visit Type";
                } else {
                    if (checkedArray.length === 1) {
                        $scope.selectVisitType = checkedArray[0].Name;
                    } else {
                        $scope.selectVisitType = "All Visit Type";
                    }
                }
            }
            let checkedAppointmentStatusArray = [];
            if ($scope.AppointmentStatusArray.length > 0) {
                checkedAppointmentStatusArray = _.where($scope.AppointmentStatusArray, { IsChecked: true });
            }

            let checkedBookedstatusFilterList = [];
            if ($scope.BookedstatusFilterList.length > 0) {
                checkedBookedstatusFilterList = _.where($scope.BookedstatusFilterList, { IsChecked: true });
            }

            var checkedProfileStatusList = [];
            if ($scope.ProfileStatusList.length > 0) {
                checkedProfileStatusList = _.where($scope.ProfileStatusList, { IsChecked: true });
            }
           
          

            $scope.getdoctorsandvisitreasonsdata(pagetype);
        }
        function onTypesFailed(err) {
            console.log(err);
        }

        
    }


