    /* ==========================================================================
       Bulk (doctor-wise) appointment cancellation
       --------------------------------------------------------------------------
       The popup first loads every not-checked-in appointment of the organization
       for the selected date range. Picking a doctor filters the list to that
       doctor and ticks all of their appointments; the user can then untick the
       ones to keep. Only one doctor is cancelled per run.

       Each selected appointment is sent with the same payload the single cancel
       popup builds, so the API pushes it through AddUpdateAppointmentNew and the
       cancellation status, SMS / Email alerts and history behave identically.
       ========================================================================== */
    $scope.BulkCancelObj = {
        "Ispopup": false,
        "IsLoading": false,
        "IsSaving": false,
        "ConsultationDt": new Date(),
        "LocationId": "",
        "VisitReasons": [],
        "VisitReasonId": "",
        "FromTime": null,
        "ToTime": null,
        "DoctorList": [],
        "SelectedDoctorId": "",
        "SelectedDoctorName": "",
        "AllAppointments": [],
        "Appointments": [],
        "TotalCount": 0,
        "EligibleCount": 0,
        "ExcludedCount": 0,
        "CancelAppReason": [],
        "CancelReasonId": null,
        "OtherCancelReason": "",
        "sendDocSms": false,
        "sendPatientSms": false,
        "sendDocEmail": false,
        "sendPatientEmail": false,
        "IsAllSelected": false
    };

    // Joins every id of a filter array into the comma separated string the appointment
    // procedures expect. The bulk popup deliberately ignores the isChecked / IsChecked
    // state of these arrays: it always asks for the full set and narrows the result with
    // AppointmentStatusIds instead, so the list does not depend on the screen filters.
    // Id 0 is the "All" placeholder row (branches), so it is skipped.
    function JoinBulkCancelIds(list, key) {
        var ids = [];
        angular.forEach(list || [], function (item) {
            if (item && item[key] !== undefined && item[key] !== null && item[key] !== "" && item[key] !== 0) {
                ids.push(item[key]);
            }
        });
        return ids.join(",");
    }

    // The branch list carries a ClinicId 0 "All" row that must not appear as a location.
    // allBranchesData holds every branch of the sub organization, so the list is narrowed
    // to the branches the logged-in user has access to - the same UserAddress list the
    // login screen offers under "Select Your Branch".
    function GetBulkCancelUserBranchIds() {
        var userAddress = (doctorInfo && doctorInfo.doctordata && doctorInfo.doctordata.UserAddress) || [];
        return userAddress.map(function (address) { return Number(address.ClinicId); });
    }

    // A doctor (RoleId 1) works on their own schedule only: the doctor list holds just
    // them and only their appointments are listed. Other roles (reception etc.) see every
    // doctor of the branch.
    function IsBulkCancelDoctorLogin() {
        return Number($scope.userLoginDetails && $scope.userLoginDetails.RoleID) === 1;
    }

    function GetBulkCancelLoginDoctor() {
        var user = (doctorInfo && doctorInfo.doctordata && doctorInfo.doctordata.User && doctorInfo.doctordata.User[0]) || {};
        return { "DoctorID": user.DoctorID, "DoctorFullName": user.FullName || "" };
    }

    $scope.BulkCancelBranchFilter = function (item) {
        return !!item && item.ClinicId !== 0 && GetBulkCancelUserBranchIds().indexOf(Number(item.ClinicId)) !== -1;
    };

    // An appointment can be cancelled only while the patient has not checked in, which is
    // the same rule CancelAppointmentPatient applies for a single cancel. Rows that fail
    // this are still listed, greyed out, so the user can see why they were left out.
    function IsBulkCancelEligible(item) {
        return item.AppointmentStatus !== "C"
            && item.AppointmentStatusId === 1
            && item.DoctorVisitRsnID !== 8
            && (item.CheckinStatusId || 1) === 1;
    }

    $scope.OpenBulkCancelPopup = function () {
        $scope.BulkCancelObj.Ispopup = true;
        $scope.BulkCancelObj.IsDoctorLogin = IsBulkCancelDoctorLogin();
        $scope.BulkCancelObj.CancelReasonId = null;
        $scope.BulkCancelObj.OtherCancelReason = "";
        $scope.BulkCancelObj.sendDocSms = false;
        $scope.BulkCancelObj.sendDocEmail = false;
        $scope.BulkCancelObj.sendPatientSms = false;
        $scope.BulkCancelObj.sendPatientEmail = false;
        $scope.BulkCancelObj.VisitReasonId = "";
        $scope.BulkCancelObj.FromTime = null;
        $scope.BulkCancelObj.ToTime = null;
        $scope.BulkCancelObj.ConsultationDt = new Date($scope.SearchObj.ConsultationDt || $scope.SearchObj.FromDate || new Date());

        // Cancel reasons and visit reasons are set up per location, so one location is
        // always selected - "All Locations" would list reasons that do not exist at the
        // branch the appointment belongs to. Start on the branch the screen is showing.
        $scope.BulkCancelObj.LocationId = DefaultBulkCancelLocationId();

        $scope.OnBulkCancelLocationChange();
    };

    function DefaultBulkCancelLocationId() {
        if ($scope.AppListselectedclinic && $scope.AppListselectedclinic.ClinicId
            && $scope.BulkCancelBranchFilter($scope.AppListselectedclinic)) {
            return $scope.AppListselectedclinic.ClinicId;
        }
        var branch = $filter("filter")($scope.AppListdoctoraddress || [], $scope.BulkCancelBranchFilter)[0];
        return branch ? branch.ClinicId : $scope.HospitalId;
    }

    // Everything that is branch specific reloads together: the reason lists the popup
    // offers and the appointments it lists.
    // Location decides which doctors, visit reasons and cancel reasons exist, so changing
    // it reloads those three and then the day's appointments for every doctor of the
    // branch. The appointment load is chained onto the doctor load on purpose: the request
    // needs the branch's doctor ids, and an empty id list means "match nothing".
    $scope.OnBulkCancelLocationChange = function () {
        $scope.BulkCancelObj.CancelReasonId = null;
        $scope.BulkCancelObj.VisitReasonId = "";
        $scope.BulkCancelObj.SelectedDoctorId = "";
        $scope.BulkCancelObj.SelectedDoctorName = "";
        ClearBulkCancelGrid();
        $scope.LoadBulkCancelCancelReasons();

        var loading = $scope.LoadBulkCancelLocationData();
        if (loading && loading.then) {
            loading.then(function () { $scope.LoadBulkCancelAppointments(); });
        }
    };

    function ClearBulkCancelGrid() {
        $scope.BulkCancelObj.AllAppointments = [];
        $scope.BulkCancelObj.Appointments = [];
        $scope.BulkCancelObj.IsAllSelected = false;
        $scope.BulkCancelObj.TotalCount = 0;
        $scope.BulkCancelObj.EligibleCount = 0;
        $scope.BulkCancelObj.ExcludedCount = 0;
    }

    // Visit reasons and providers are per branch, so both are fetched for the selected
    // location with the same two calls this screen already uses when its own branch
    // changes (GetOrganizationActiveAndInActiveApptVisitReasons + GetAllUsersByDeptId).
    // They land in the popup's own lists, so the screen behind keeps its filters.
    $scope.LoadBulkCancelLocationData = function () {
        var locationId = $scope.BulkCancelObj.LocationId;
        $scope.BulkCancelObj.VisitReasons = [];
        $scope.BulkCancelObj.DoctorList = [];
        if (!locationId) { return; }

        return $q.all([
            eHnotePatientVisitReasonServices.GetOrganizationActiveAndInActiveApptVisitReasons({
                "OrganizationId": locationId,
                "VisitTypeId": 0,
                "SearchText": ""
            }),
            eHnoteMainAppointmentService.getAllUsersByDepartmentIdNew({
                "BranchId": locationId
            })
        ]).then(function (resp) {
            $scope.BulkCancelObj.VisitReasons = (resp[0] && resp[0].data && resp[0].data.rows) || [];
            $scope.BulkCancelObj.DoctorList = BuildBulkCancelDoctorList((resp[1] && resp[1].data && resp[1].data.rows) || []);

            // a doctor has only themselves to pick, so pick it for them
            if (IsBulkCancelDoctorLogin() && $scope.BulkCancelObj.DoctorList.length) {
                $scope.BulkCancelObj.SelectedDoctorId = $scope.BulkCancelObj.DoctorList[0].DoctorID;
                $scope.BulkCancelObj.SelectedDoctorName = $scope.BulkCancelObj.DoctorList[0].DoctorFullName;
            }
        }, function () {
            alertify.error("Error in loading this location's doctors and visit reasons");
        });
    };

    $scope.CloseBulkCancelPopup = function () {
        $scope.BulkCancelObj.Ispopup = false;
    };

    $scope.LoadBulkCancelCancelReasons = function () {
        var getParams = {
            // per selected location, not the login branch - the reasons differ by branch
            "OrganizationId": $scope.BulkCancelObj.LocationId || $scope.HospitalId,
            "PageSize": 100,
            "PageNumber": 1
        };
        $scope.BulkCancelObj.CancelAppReason = [];
        return eHnotePatientVisitReasonServices.getOrganizationCancelVisitReasons(getParams).then(function (resp) {
            if (resp.data !== undefined && resp.data.rows !== undefined && resp.data.rows.length > 0) {
                $scope.BulkCancelObj.CancelAppReason = $filter("filter")(resp.data.rows, { "ActiveInd": "Y" }, true);
            }
        });
    };

    // Loads the appointments of every doctor in the organization for the chosen date, using
    // the same service and the same status ids the OP appointment list uses for its
    // Reception tiles: 1 = Not Checked In (cancellable), 2 = Check In (listed but excluded).
    $scope.LoadBulkCancelAppointments = function () {
        if (!$scope.BulkCancelObj.LocationId) {
            alertify.error("Please Select a Location");
            return;
        }
        // the doctor selection survives a reload; it narrows the rows, it is not the query
        $scope.BulkCancelObj.IsLoading = true;
        ClearBulkCancelGrid();

        // every doctor of the branch - an empty id list would match nothing
        var doctorIds = JoinBulkCancelIds($scope.BulkCancelObj.DoctorList, "DoctorID");

        // one location at a time, so the reasons offered always belong to the branch
        var locationIds = String($scope.BulkCancelObj.LocationId || "");

        // the popup's own per-location list, not the screen's visit reason filter
        var visitReasonIds = $scope.BulkCancelObj.VisitReasonId
            ? String($scope.BulkCancelObj.VisitReasonId)
            : JoinBulkCancelIds($scope.BulkCancelObj.VisitReasons, "ParentAppointmentVisitReasonId");

        var params = {
            "UserBranchId": doctorInfo.doctordata.UserAddress[0].UserBranchId,
            "HospitalID": doctorInfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
            "ConsultationDt": $filter("date")(new Date($scope.BulkCancelObj.ConsultationDt), "yyyy-MM-dd"),
            "DoctorIds": doctorIds,
            "PageSize": 600,
            "PageNumber": 1,
            "SearchText": "",
            "SearchPatientId": "",
            "RoleId": $scope.userLoginDetails.RoleID,
            "SortType": $scope.SortType,
            "SortBy": $scope.SortBy,
            "SpecializationId": $scope.selectedSpecializationId,
            "SubSpecializationIds": "",
            "UserId": eHnoteMasterDataService.getLoginId(),
            "GetAllAppointmentStatusInd": true,
            "GetAllVisitStatusInd": true,
            "GetAllAppointmentTypeStatusInd": true,
            "AppointmentStatusIDLst": JoinBulkCancelIds($scope.AppointmentStatusFilterArray, "Id"),
            "VisitStatusIDLst": JoinBulkCancelIds($scope.AppointmentVisitFilterArray, "Id"),
            "AppointmentTypeStatusIDList": JoinBulkCancelIds($scope.appointmentTypes, "Id"),
            "CheckInStatusIds": JoinBulkCancelIds($scope.CheckInFilterArray, "Id"),
            "VisitReasonIdList": visitReasonIds,
            "BookingTypeIds": JoinBulkCancelIds($scope.BookingTypesArray, "BookingTypeId"),
            "ProfileStatusIds": JoinBulkCancelIds($scope.ProfileStatusList, "Id"),
            "BookingStatusIds": JoinBulkCancelIds($scope.BookedstatusFilterList, "Id"),
            "PatientTagListIds": "",
            "AppointmentStatusIds": "1,2", // Not Checked In + Check In
            "ChartStatusIds": "1,2",       // Not Signed + Signed, the full set the OP list posts
            "FacilityListIds": "",
            "Locationids": locationIds
        };

        eHnoteMainAppointmentService.GetCheckInOutAppointmentList(params, OnBulkCancelListSuccess, OnBulkCancelListError);
    };

    function OnBulkCancelListSuccess(bookdata) {
        $scope.BulkCancelObj.IsLoading = false;

        var rows = [];


        // DoctorIds already limits a doctor's request to themselves; this keeps another
        // doctor's rows out even if the service returns more than was asked for.
        var loginDoctorId = IsBulkCancelDoctorLogin() ? GetBulkCancelLoginDoctor().DoctorID : 0;

        angular.forEach((bookdata && bookdata.AppointmentList) || [], function (item) {
            if (loginDoctorId && Number(item.DoctorID) !== Number(loginDoctorId)) { return; }
            var patient = item.Patient || {};

            // UsMobileFormatChange expects a string and throws on numbers with no digits,
            // so keep a plain fallback for patients without a usable mobile number.
            var mobileObj = { "UsFormatMobileNumber": "" };
            try {
                mobileObj = eHnoteUserDataService.UsMobileFormatChange(String(patient.MobileNo || ""));
            } catch (mobileErr) {
                mobileObj = { "UsFormatMobileNumber": String(patient.MobileNo || "") };
            }

            var isEligible = IsBulkCancelEligible(item);

            rows.push({
                "IsSelected": false,
                "IsEligible": isEligible,
                "StatusText": GetBulkCancelStatusText(item, isEligible),
                "StatusClass": GetBulkCancelStatusClass(item, isEligible),
                "AppointmentID": item.AppointmentID,
                "PatientID": item.PatientID,
                "PatientName": patient.FullName || "",
                "PatientDisplayId": patient.PatientDisplayId || "",
                "PatientDOB": patient.DOB || "",
                "PatientMobile": patient.MobileNo || "",
                "PatientDisplayNumber": mobileObj.UsFormatMobileNumber || "",
                "PatientEmail": patient.EmailId || "",
                "PatientLanguageID": patient.LanguageID || 0,
                "IsPatientSmsInd": patient.IsPatientSmsInd || false,
                "IsPatientEmailInd": patient.IsPatientEmailInd || false,
                "DoctorID": item.DoctorID,
                "DoctorFullName": item.DoctorFullName || "",
                "DoctorEmail": item.DoctorEmail || "",
                "DoctorMobile": item.DoctorMobile || "",
                "HospitalId": item.HospitalId,
                "UserBranchId": item.UserBranchId,
                "BranchName": item.BranchName || "",
                "ConsultationDt": item.ConsultationDt,
                "StartTime": item.StartTime,
                "EndTime": item.EndTime,
                "AppointmentDateTime": item.ConsultationDt + "T" + item.StartTime,
                "VisitReason": item.VisitReason || item.OtherVisitRsn || "",
                "AppointmentStatusName": item.AppointmentStatusName || "",
                "AppointmentStatus": item.AppointmentStatus,
                "AppointmentStatusId": item.AppointmentStatusId,
                "BookingStatusId": item.BookingStatusId,
                "BookingTypeId": item.BookingTypeId,
                "DoctorVisitRsnID": item.DoctorVisitRsnID,
                "CheckinStatusId": item.CheckinStatusId || 1,
                "VisitTypeId": item.VisitTypeId || null,
                "SubSpecializationId": item.SubSpecializationId,
                "BranchSubSpecializationId": item.BranchSubSpecializationId,
                "AppointmentPatientTypeId": item.AppointmentPatientTypeId || 1,
                "PaymentTypeId": item.PaymentTypeId || 0,
                "VisitRemarks": item.VisitRemarks || "",
                "IsTeleMedicineSlot": item.IsTeleMedicineSlot || false,
                "IsConfirmedAppointment": item.IsConfirmedAppointment || false,
                "CommunicationEmailId": item.CommunicationEmailId || "",
                "CommunicationMobileNo": item.CommunicationMobileNo || "",
                "OtherProviderDoctorID": item.OtherProviderDoctorID || 0,
                "SurgeryReferralDoctorId": item.SurgeryReferralDoctorId || 0,
                "ReasonTypeId": item.ReasonTypeId || 0,
                "TokenNumber": item.TokenNumber || 0
            });
        });

        $scope.BulkCancelObj.AllAppointments = rows;
        // a reload keeps the chosen doctor, so re-tick their cancellable rows
        var doctorId = $scope.BulkCancelObj.SelectedDoctorId || 0;
        angular.forEach(rows, function (row) {
            row.IsSelected = doctorId !== 0 && row.DoctorID === doctorId && row.IsEligible;
        });
        $scope.ApplyBulkCancelFilters();
    }

    function GetBulkCancelStatusText(item, isEligible) {
        if (!isEligible) {
            return item.AppointmentStatusName || "Not Cancellable";
        }
        return item.BookingStatusId === 1 ? "Confirmed" : "Not Confirmed";
    }

    function GetBulkCancelStatusClass(item, isEligible) {
        if (!isEligible) {
            return "bc-chip-muted";
        }
        return item.BookingStatusId === 1 ? "bc-chip-green" : "bc-chip-red";
    }

    // Keeps only the provider roles, the same set getDoctorsbySubSpecializations uses for
    // the screen's own doctor list, deduped by DoctorID.
    function BuildBulkCancelDoctorList(users) {
        var list = [];
        angular.forEach(users || [], function (d) {
            if (!d || !d.DoctorID) { return; }
            var isProvider = d.RoleId === 1 || d.RoleId === 3 || d.RoleId === 4 || d.RoleId === 43
                || d.RoleId === 16 || d.RoleId === 56 || d.RoleId === 57;
            if (!isProvider) { return; }
            if (!$filter("filter")(list, { "DoctorID": d.DoctorID }, true).length) {
                list.push({ "DoctorID": d.DoctorID, "DoctorFullName": d.FullName || d.DoctorFullName || "" });
            }
        });

        if (IsBulkCancelDoctorLogin()) {
            // the logged-in doctor only; fall back to their login record when the branch
            // user list does not carry them
            var loginDoctor = GetBulkCancelLoginDoctor();
            if (!loginDoctor.DoctorID) { return []; }
            var own = list.filter(function (d) { return Number(d.DoctorID) === Number(loginDoctor.DoctorID); });
            return own.length ? own : [loginDoctor];
        }

        return $filter("orderBy")(list, "DoctorFullName");
    }

    function OnBulkCancelListError() {
        $scope.BulkCancelObj.IsLoading = false;
        $scope.BulkCancelObj.AllAppointments = [];
        $scope.BulkCancelObj.Appointments = [];
        $scope.BulkCancelObj.TotalCount = 0;
        $scope.BulkCancelObj.EligibleCount = 0;
        $scope.BulkCancelObj.ExcludedCount = 0;
        alertify.error("Error in listing Appointments");
    }

    // Minutes since midnight, so a time range can be compared without a date.
    // input[type="time"] binds a Date (1970-01-01T09:14) while the appointment rows carry
    // an "HH:mm:ss" string, so both shapes have to be handled.
    function BulkCancelTimeToMinutes(time) {
        if (time === null || time === undefined || time === "") {
            return null;
        }
        if (angular.isDate(time)) {
            return isNaN(time.getTime()) ? null : (time.getHours() * 60) + time.getMinutes();
        }
        var parts = String(time).split(":");
        if (parts.length < 2) {
            return null;
        }
        var hours = parseInt(parts[0], 10);
        var minutes = parseInt(parts[1], 10);
        if (isNaN(hours) || isNaN(minutes)) {
            return null;
        }
        return (hours * 60) + minutes;
    }

    // Applies the doctor and time range filters to the loaded rows. Location, date and
    // visit reason are applied by the service, so they are not repeated here.
    // Location, date and visit reason are applied by the service; doctor and time range
    // narrow what came back, so no doctor selected means the whole branch is on show.
    $scope.ApplyBulkCancelFilters = function () {
        var doctorId = $scope.BulkCancelObj.SelectedDoctorId || 0;
        var fromMinutes = BulkCancelTimeToMinutes($scope.BulkCancelObj.FromTime);
        var toMinutes = BulkCancelTimeToMinutes($scope.BulkCancelObj.ToTime);

        var filtered = [];
        angular.forEach($scope.BulkCancelObj.AllAppointments, function (row) {
            if (doctorId !== 0 && row.DoctorID !== doctorId) {
                return;
            }
            var startMinutes = BulkCancelTimeToMinutes(row.StartTime);
            if (fromMinutes !== null && startMinutes !== null && startMinutes < fromMinutes) {
                return;
            }
            if (toMinutes !== null && startMinutes !== null && startMinutes > toMinutes) {
                return;
            }
            filtered.push(row);
        });

        $scope.BulkCancelObj.Appointments = filtered;
        $scope.BulkCancelObj.TotalCount = filtered.length;
        $scope.BulkCancelObj.EligibleCount = $filter("filter")(filtered, { "IsEligible": true }, true).length;
        $scope.BulkCancelObj.ExcludedCount = filtered.length - $scope.BulkCancelObj.EligibleCount;

        // A row that dropped out of the filter must not stay selected.
        angular.forEach($scope.BulkCancelObj.AllAppointments, function (row) {
            if (filtered.indexOf(row) === -1) {
                row.IsSelected = false;
            }
        });

        $scope.OnBulkCancelAppointmentToggle();
    };

    // Picking a doctor narrows the list to that doctor and ticks all of their cancellable
    // appointments; the user unticks whatever should stay booked.
    // The whole branch is already loaded, so picking a doctor narrows the grid to them and
    // ticks their cancellable appointments. Only one doctor is cancelled per run.
    $scope.OnBulkCancelDoctorChange = function () {
        var doctorId = $scope.BulkCancelObj.SelectedDoctorId || 0;
        var selectedDoctor = $filter("filter")($scope.BulkCancelObj.DoctorList, { "DoctorID": doctorId }, true)[0];
        $scope.BulkCancelObj.SelectedDoctorName = selectedDoctor ? selectedDoctor.DoctorFullName : "";

        angular.forEach($scope.BulkCancelObj.AllAppointments, function (row) {
            row.IsSelected = doctorId !== 0 && row.DoctorID === doctorId && row.IsEligible;
        });

        $scope.ApplyBulkCancelFilters();
    };

    $scope.ToggleBulkCancelSelectAll = function () {
        if (!$scope.BulkCancelObj.SelectedDoctorId) {
            $scope.BulkCancelObj.IsAllSelected = false;
            alertify.error("Please Select a Doctor");
            return;
        }
        angular.forEach($scope.BulkCancelObj.Appointments, function (row) {
            row.IsSelected = row.IsEligible && $scope.BulkCancelObj.IsAllSelected;
        });
    };

    $scope.OnBulkCancelAppointmentToggle = function () {
        var eligible = $filter("filter")($scope.BulkCancelObj.Appointments, { "IsEligible": true }, true);
        $scope.BulkCancelObj.IsAllSelected = eligible.length > 0
            && $filter("filter")(eligible, { "IsSelected": true }, true).length === eligible.length;
    };

    $scope.GetBulkCancelSelectedAppointments = function () {
        return $filter("filter")($scope.BulkCancelObj.Appointments, { "IsSelected": true, "IsEligible": true }, true);
    };

    $scope.GetBulkCancelSelectedCount = function () {
        return $scope.GetBulkCancelSelectedAppointments().length;
    };

    // Builds the same request the single cancel popup posts, for one appointment.
    function BuildBulkCancelPayload(row, cancelReasonId, otherCancelReason) {
        var currentdaycode = $filter("date")($scope.getCurrentDate(), "EEE").toUpperCase();
        var CurrentDate = $filter("date")(new Date(), "yyyy-MM-dd");
        var CurrentCheckOutTime = $filter("date")(new Date(), "HH:mm:ss");

        var appointmentStatusId = 5; // planned cancel
        if (row.ConsultationDt === CurrentDate) {
            if (row.AppointmentStatusId === 1) {
                appointmentStatusId = 7; // same day cancel
            } else if (row.AppointmentStatusId === 2) {
                appointmentStatusId = 6; // check-in cancel
            } else {
                appointmentStatusId = row.AppointmentStatusId;
            }
        }

        var AppmntParams = {
            "AppointmentID": row.AppointmentID,
            "AppointmentStatus": "C",
            "StartTime": row.StartTime,
            "EndTime": row.EndTime,
            "IsFollowUp": false,
            "DoctorID": row.DoctorID,
            "UserBranchId": doctorInfo.doctordata.UserAddress[0].UserBranchId,
            "DayCD": currentdaycode,
            "VisitUserTypeID": "OPATIENT",
            "OtherVisitRsn": "",
            "ConsultationDt": row.ConsultationDt,
            "PatientID": row.PatientID,
            "UserId": eHnoteMasterDataService.getLoginId(),
            "USRType": "DOCTOR",
            "DoctorVisitRsnID": row.DoctorVisitRsnID,
            "HospitalDetails": {
                "HospitalID": row.HospitalId,
                "LoginHospitalID": doctorInfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
                "ParentHospitalID": doctorInfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.ParentHospitalID,
                "SenderId": doctorInfo.doctordata.UserAddress[0].SMSSenderId,
                "IsSMSInd": doctorInfo.doctordata.UserAddress[0].IsSMSInd
            },
            "CommunicationDetails": {
                "PatientName": row.PatientName,
                "PatientMobile": row.PatientMobile,
                "DoctorMobile": row.DoctorMobile,
                "HospitalName": doctorInfo.doctordata.UserAddress[0].ClinicName,
                "DoctorName": row.DoctorFullName,
                "AppDate": row.ConsultationDt,
                "AppTime": row.StartTime,
                "AppClinic": doctorInfo.doctordata.UserAddress[0].ClinicName,
                "AppToken": 0,
                "PatientEmail": row.PatientEmail,
                "BranchEmail": doctorInfo.doctordata.UserAddress[0].BranchEmail || "",
                "DoctorEmail": row.DoctorEmail,
                "HospitalContact": doctorInfo.doctordata.UserAddress[0].MobileNo,
                "BrnachAddress": {
                    "Address1": doctorInfo.doctordata.UserAddress[0].Address1,
                    "Address2": doctorInfo.doctordata.UserAddress[0].Address2,
                    "Location": doctorInfo.doctordata.UserAddress[0].Location,
                    "StateId": doctorInfo.doctordata.UserAddress[0].StateId,
                    "PinCode": doctorInfo.doctordata.UserAddress[0].PinCode,
                    "CountryId": doctorInfo.doctordata.UserAddress[0].CountryId,
                    "CityId": doctorInfo.doctordata.UserAddress[0].CityId,
                    "DistrictRegion": doctorInfo.doctordata.UserAddress[0].DistrictRegion,
                    "Latitude": doctorInfo.doctordata.UserAddress[0].Latitude,
                    "Longitude": doctorInfo.doctordata.UserAddress[0].Longitude
                },
                "CommunicationEmailId": row.CommunicationEmailId,
                "CommunicationMobileNo": row.CommunicationMobileNo,
                "DisplayNumber": row.PatientDisplayNumber
            },
            "PreviousAppointmentTime": "",
            "SendDocSms": $scope.BulkCancelObj.sendDocSms,
            "SendDocEmail": $scope.BulkCancelObj.sendDocEmail,
            "SendPatientEmail": $scope.BulkCancelObj.sendPatientEmail,
            "SendPatientSms": $scope.BulkCancelObj.sendPatientSms,
            "StatusDescription": otherCancelReason || "",
            "PaidFollowup": false,
            "IsTeleMedicineSlot": row.IsTeleMedicineSlot,
            "SubSpecializationId": row.SubSpecializationId,
            "BranchSubSpecializationId": row.BranchSubSpecializationId,
            "CurrentTime": CurrentCheckOutTime || null,
            "IsCheckedIn": row.CheckinStatusId || 1,
            "VisitTypeId": row.VisitTypeId || null,
            "AppointmentPatientTypeId": row.AppointmentPatientTypeId || 1,
            "CancelReasonId": cancelReasonId || 0,
            "VisitRemarks": row.VisitRemarks || "",
            "PaymentTypeId": row.PaymentTypeId || 0,
            "PatientSmsLanguageId": 152,
            "IsNoShowAppointment": false,
            "IsConfirmedAppointment": row.IsConfirmedAppointment,
            "BookingStatusId": row.BookingStatusId,
            "AppointmentStatusId": appointmentStatusId,
            "BookingTypeId": row.BookingTypeId,
            "OtherProviderDoctorID": row.OtherProviderDoctorID || 0,
            "SurgeryReferralDoctorId": row.SurgeryReferralDoctorId || 0,
            "ReasonTypeId": row.ReasonTypeId || 0,
            "SmsLanguageId": 123, // english
            "ParentAppointmentVisitReasonId": row.VisitTypeId || null,
            "EmailCommunicationProviderId": doctorInfo.doctordata.UserAddress[0].EmailCommunicationProviderId || 0,
            "EmailCommunicationEnabled": doctorInfo.doctordata.UserAddress[0].EmailCommunicationEnabled || false
        };

        // Same per-environment SMS language / suppression rules as the single cancel.
        var currenturl = $location.absUrl().split("?")[0];
        var CurrentEnvironment = currenturl.split("/#")[0];
        var selectedPatientLanguageId = row.PatientLanguageID || 0;

        if (CurrentEnvironment === "https://ioj.ehnote.com" || CurrentEnvironment === "https://insts.ehnote.com") {
            AppmntParams.SmsLanguageId = selectedPatientLanguageId === 123 ? 123 : 401; // spanish
            if (AppmntParams.DoctorVisitRsnID == "4" || AppmntParams.DoctorVisitRsnID == "7" || AppmntParams.DoctorID == 3 || AppmntParams.DoctorID == 4 ||
                AppmntParams.VisitTypeId == 8 || AppmntParams.VisitTypeId == 9 || AppmntParams.VisitTypeId == 10 || AppmntParams.VisitTypeId == 11 || AppmntParams.VisitTypeId == 28 || AppmntParams.VisitTypeId == 29) {
                AppmntParams.SendDocSms = false;
                AppmntParams.SendPatientSms = false;
                AppmntParams.IsOnboadringUrlInd = false;
                AppmntParams.SendPatientEmail = false;
            }
        } else if (CurrentEnvironment === "https://portal.ehnote.com" || CurrentEnvironment === "https://stage.ehnote.com") {
            if (selectedPatientLanguageId !== 0) {
                AppmntParams.SmsLanguageId = selectedPatientLanguageId;
            }
            if (AppmntParams.DoctorVisitRsnID == "4" || AppmntParams.DoctorVisitRsnID == "7") { // Only for Tec
                AppmntParams.IsOnboadringUrlInd = false;
                AppmntParams.SendDocSms = false;
                AppmntParams.SendPatientSms = false;
                AppmntParams.SendPatientEmail = false;
            }
        }

        return AppmntParams;
    }

    $scope.BulkCancelSelectedAppointments = function () {
        var cancelReasonId = $scope.BulkCancelObj.CancelReasonId || 0;
        var otherCancelReason = $scope.BulkCancelObj.OtherCancelReason || "";

        if (!$scope.BulkCancelObj.SelectedDoctorId) {
            alertify.error("Please Select a Doctor");
            return false;
        }

        var selected = $scope.GetBulkCancelSelectedAppointments();
        if (selected.length === 0) {
            alertify.error("Please Select at least one Appointment to Cancel");
            return false;
        }

        if (cancelReasonId === 0) {
            alertify.error("Please Select Reason For Cancellation");
            return false;
        }

        // Same mandatory-other-reason rule the single cancel applies.
        if ($scope.ParentObj && $scope.ParentObj.IsIOJParentOrganization) {
            if (otherCancelReason === "") {
                alertify.error("Please Enter Reason for Cancel");
                return false;
            }
        } else if (cancelReasonId === 1 && otherCancelReason === "") {
            alertify.error("Please Enter Reason for Cancel");
            return false;
        }

        // Cancelling in bulk cannot be undone, so confirm the doctor and the count first.
        var doctorName = $scope.BulkCancelObj.SelectedDoctorName || "this doctor";
        var confirmText = "<b class='txt-centre'>Confirm !</b>"
            + "<h4 class='txt-body-centre'>Are you sure you want to cancel "
            + selected.length + " appointment" + (selected.length === 1 ? "" : "s")
            + " of Dr." + doctorName + " ?</h4>";

        // alertify fires its callback outside the digest, so re-enter Angular with $timeout.
        alertify.confirm(confirmText, function () {
            $timeout(function () {
                SubmitBulkCancelAppointments(selected, cancelReasonId, otherCancelReason);
            });
        });
    };

    function SubmitBulkCancelAppointments(selected, cancelReasonId, otherCancelReason) {
        var selectedReason = $filter("filter")($scope.BulkCancelObj.CancelAppReason, { "CancelVisitReasonId": cancelReasonId }, true)[0];

        var params = {
            "DoctorID": $scope.BulkCancelObj.SelectedDoctorId,
            "DoctorName": $scope.BulkCancelObj.SelectedDoctorName,
            "CancelReasonId": cancelReasonId,
            "CancelReason": selectedReason ? selectedReason.CancelReason : "",
            "Appointments": selected.map(function (row) {
                return BuildBulkCancelPayload(row, cancelReasonId, otherCancelReason);
            })
        };

        $scope.BulkCancelObj.IsSaving = true;
        eHnoteUserAppointmentDataService.BulkCancelAppointmentsService(params, OnBulkCancelSuccess, OnBulkCancelError);
    }

    function OnBulkCancelSuccess(data) {
        $scope.BulkCancelObj.IsSaving = false;

        var cancelledCount = (data && data.CancelledCount) || 0;
        var failedCount = (data && data.FailedCount) || 0;

        if (cancelledCount === 0) {
            alertify.error((data && data.Message) || "Error in Cancelling Appointments");
            return;
        }

        if (failedCount > 0) {
            alertify.error(cancelledCount + " Appointment(s) Cancelled, " + failedCount + " Failed");
        } else {
            alertify.success(cancelledCount + " Appointment(s) Cancelled Successfully");
        }

        $scope.BulkCancelObj.Ispopup = false;
        $scope.loadAppointments($scope.selectedDoctor, "");
    }

    function OnBulkCancelError() {
        $scope.BulkCancelObj.IsSaving = false;
        alertify.error("Error in Cancelling Appointments");
    }

