            $scope.cacheStorageItem.FollowUpDurationType = plan.FollowUpDurationType ? plan.FollowUpDurationType : "D";
            $scope.cacheStorageItem.FollowUpNotes = plan.FollowUpNotes ? plan.FollowUpNotes : "";
