    $scope.ViewDilationHistory = function (item) {
        $scope.mInstanceAdd = $uibModal.open({
            "templateUrl": "templates/Op/DilationHistoryPopup.html",
            "backdrop": "static",
            "scope": $scope,
            "keyboard": false,
            "size": "lg",
            "controller": function ($scope, $uibModal, $uibModalInstance, eHnotePatientPVService, eHnotePatientDataService) {

                var obj = {
                    "PatientId": item.PatientID,
                    "AppointmentId": item.AppointmentID
                }
                eHnotePatientDataService.GetDilationHistory(obj).then(function (resp) {
                    $scope.DilationHistoryArray = resp.data.rows || [];
                    // $scope.Medication.DilationHistoryId = $scope.DilationHistoryArray.length != 0 ? $scope.DilationHistoryArray[0].DilationHistoryId : 0;
                    if ($scope.DilationHistoryArray.length > 0) {
                        angular.forEach($scope.DilationHistoryArray, function (kitem) {
                            kitem.Duration = "";
                            if (kitem.DilationEndTime != null && kitem.DilationStartTime != null) {
                                var ms = moment(kitem.DilationEndTime, "YYYY-MM-DD HH:mm:ss").diff(moment(kitem.DilationStartTime, "YYYY-MM-DD HH:mm:ss"));
                                var d = moment.duration(ms);
                                var s = Math.floor(d.asHours()) + moment.utc(ms).format(":mm:ss");
                                kitem.Duration = s;
                            }
                        });
                    }
                });
                $scope.closeDilationHistory = function () {
                    $uibModalInstance.dismiss("cancel");
                };
            }
        });
    }

    $scope.changeDoctor = function (item) {
        if (item != "") {
            $scope.selectedDoctor = item;
        }
        if ($scope.activeEvent == 'day') {
            var avgConsultationTime = item.MinPerCase;
            sliceTime = item.MinPerCase;
            angular.element('#calControl').fullCalendar('option', {
                defaultTimedEventDuration: '00:' + avgConsultationTime + ':00',
                slotDuration: '00:' + avgConsultationTime + ':00',

            });
            setTimeout(function () {
                angular.element('.fc-scroller').scrollTop(0);
                if ($('.fc-now-indicator-line').offset()) {
                    angular.element('.fc-scroller').scrollTop($('.fc-now-indicator-line').offset().top - 300);
                }
            }, 1000);
            $scope.renderCalendar('calControl');

            onclick();
        }
    }
