    $scope.selectedBranchStringUpdate = function () {
        let selected = $scope.AllApptBranchLocations.filter(item => item.IsChecked);
        if (selected.length === 0) {
            $scope.shared.selectLocationString = '';
        } else if (selected.length === 1) {
            $scope.shared.selectLocationString = selected[0].BranchName;
        } else if (selected.length === $scope.AllApptBranchLocations.length) {
            $scope.shared.selectLocationString = 'All Locations';
        } else {
            $scope.shared.selectLocationString = 'Selected';
        }
    }
