    $scope.SearchAppoint = function (type) {

        if (!eHnoteMainAppointmentService.Is14DaysCount($scope.SearchObj.ConsultationDtFromDate, $scope.SearchObj.ConsultationDtTodate)) {
            alertify.log("More than 14 days not allowed");
            return;
        }

        if (type == "ByDoctor") {
            var count = 0;
            angular.forEach($scope.sharedDoctors.MultiselectDoctorlist, function (item) {
                if (item.isCheckedList == true) {
                    count++;
                }
            });
            if (count == 0) {
                alertify.error("Please Choose Atleast One Doctor");
                return;
            }
        }
        if (type == "ByVisitReason") {
            var count = 0;
            angular.forEach($scope.sharedDoctors.MultiselectDoctorlist, function (item) {
                if (item.isCheckedList == true) {
                    count++;
                }
            });
            if (count == 0) {
                alertify.error("Please Choose Atleast One Doctor");
                return;
            }

            var count1 = 0;
            angular.forEach($scope.VisitreasonsforPrint, function (item) {
                if (item.isChecked == true) {
                    count1++;
                }
            });
            if (count1 == 0) {
                alertify.error("Please Choose Atleast One VisitReason");
                return;
            }

        }
        if (type == "ByApptWiseVisitReason") {
            var count = 0;
            angular.forEach($scope.VisitreasonsforPrint, function (item) {
                if (item.isChecked == true) {
                    count++;
                }
            });
            if (count == 0) {
                alertify.error("Please Choose Atleast One VisitReason");
                return;
            }
            //if ($scope.SearchObj.selectedDoctor == "") {
            //    alertify.error("Please Select Doctor");
            //    return;
            //}
            var MDcount = 0;
            angular.forEach($scope.sharedDoctors.MultiselectDoctorlist, function (item) {
                if (item.isCheckedList == true) {
                    MDcount++;
                }
            });
            if (MDcount == 0) {
                alertify.error("Please Choose Atleast One Doctor");
                return;
            }
            $scope.GetDataVisitReasonWiseAppt();
        }
        else {
            $scope.getdata(type);
        }
        var FromDate = $filter('date')($scope.SearchObj.ConsultationDtFromDate, "yyyy-MM-dd"); //YYYY-MM-DD
        var ToDate = $filter('date')($scope.SearchObj.ConsultationDtTodate, "yyyy-MM-dd"); //YYYY-MM-DD
        var dateArr = getDateArray(FromDate, ToDate);
        console.log(dateArr);
        $scope.Datecontainer = [];
        angular.forEach(dateArr, function (item) {
            $scope.Datecontainer.push($filter('date')(new Date(item), "yyyy-MM-dd"));
        });
        $scope.DatecontainerColspan = $scope.Datecontainer.length + 1;
       
    }

    var getDateArray = function (FromDate, ToDate) {
        var arr = new Array();
        var dt = new Date(FromDate);
        while (dt <= new Date(ToDate)) {
            arr.push(new Date(dt));
            dt.setDate(dt.getDate() + 1);
        }
        return arr;
    }
    $scope.getdata = function (type) {
        $scope.DataStoring = [];
        var checkedArrayList = [];
        if ($scope.sharedDoctors.MultiselectDoctorlist.length > 0) {
            checkedArrayList = _.where($scope.sharedDoctors.MultiselectDoctorlist, { isCheckedList: true });
        }
        var newlistForPrint = "";
        for (var i in $scope.sharedDoctors.MultiselectDoctorlist) {
            if ($scope.sharedDoctors.MultiselectDoctorlist[i].isCheckedList) {
                newlistForPrint += "," + $scope.sharedDoctors.MultiselectDoctorlist[i].DoctorID;
            }
        }
        if (newlistForPrint.charAt(0) === ",") {
            newlistForPrint = newlistForPrint.slice(1);
        }

        var newVisitlist = "";
        for (var i in $scope.VisitreasonsforPrint) {
            if ($scope.VisitreasonsforPrint[i].isChecked) {
                newVisitlist += "," + $scope.VisitreasonsforPrint[i].ReasonId;
            }
        }
        if (newVisitlist.charAt(0) === ",") {
            newVisitlist = newVisitlist.slice(1);
        }
        var locationIds = $scope.AllApptBranchLocations
            .filter(pitem => pitem.IsChecked && pitem.ClinicId !== 0) // Exclude ClinicId === 0
            .map(pitem => pitem.ClinicId)
            .join(",");
        var obj = {
            "HospitalId": locationIds,
            "FromDate": $filter('date')(new Date($scope.SearchObj.ConsultationDtFromDate), "yyyy-MM-dd"),
            "ToDate": $filter('date')(new Date($scope.SearchObj.ConsultationDtTodate), "yyyy-MM-dd"),
            "DoctorIds": newlistForPrint,
            "VisitReasonIds": newVisitlist || "",
            "UserId": $scope.UserId || 0,
            "ReportName": type || "",
        };
        eHnotePatientDataService.GetAppointmentsCountByVisitReasons(obj).then(function (resp) {
            console.log(resp);
            if (resp.data.Status === 'Success') {
                $scope.DataStoring = resp.data.rows || [];
                $scope.DataStoringArray = angular.copy($scope.DataStoring);

                if ($scope.DataStoringArray.length > 0) {
                    angular.forEach($scope.DataStoringArray, function (aitem) {
                        angular.forEach(aitem.VisitReasons, function (subitem) {
                            subitem.VisitReasonDataList = [];
                            subitem.VisitReasonData = subitem.VisitReasonData || [];
                            if (subitem.VisitReasonData.length > 0) {
                                angular.forEach($scope.Datecontainer, function (ditem) {
                                    var filtervisit = $filter('filter')(subitem.VisitReasonData, { 'AppointmentDate': ditem }, true) || [];
                                    if (filtervisit.length === 0) {
                                        var obj = {
                                            "AppointmentCount": "",
                                            "AppointmentDate": ditem
                                        };
                                        subitem.VisitReasonDataList.push(obj);
                                    } else {
                                        subitem.VisitReasonDataList.push(filtervisit[0]);
                                    }
                                });
                            } else {
                                angular.forEach($scope.Datecontainer, function (ditem) {
                                    var obj = {
                                        "AppointmentCount": "",
                                        "AppointmentDate": ditem
                                    };
                                    subitem.VisitReasonDataList.push(obj);
                                });
                            }
                        });

                        if (aitem.AppointmentDatesArray.length > 0) {
                            aitem.AppointmentDatesList = [];
                            angular.forEach($scope.Datecontainer, function (ditem) {
                                var filterdate = $filter('filter')(aitem.AppointmentDatesArray, { 'AppointmentDate': ditem }, true) || [];
                                if (filterdate.length === 0) {
                                    var obj = {
                                        "AppointmentCount": "",
                                        "AppointmentDate": ditem
                                    };
                                    aitem.AppointmentDatesList.push(obj);
                                } else {
                                    aitem.AppointmentDatesList.push(filterdate[0]);
                                }
                            });
                        } else {
                            aitem.AppointmentDatesList = [];
                            angular.forEach($scope.Datecontainer, function (ditem) {
                                var obj = {
                                    "AppointmentCount": "",
                                    "AppointmentDate": ditem
                                };
                                aitem.AppointmentDatesList.push(obj);
                            });
                        }

                    });
                }
                $scope.TotalAppointmentstCountByDate = [];
                $scope.TotalAppointmentstCountByDate = angular.copy(resp.data.TotalAppointmentstCountByDate)
                if ($scope.TotalAppointmentstCountByDate.length > 0) {
                    $scope.ShowTotalAppt = [];
                    angular.forEach($scope.Datecontainer, function (ditem) {
                        var filterdate = $filter('filter')($scope.TotalAppointmentstCountByDate, { 'AppointmentDate': ditem }, true) || [];
                        if (filterdate.length === 0) {
                            var obj = {
                                "AppointmentCount": "",
                                "AppointmentDate": ditem
                            };
                            $scope.ShowTotalAppt.push(obj);
                        } else {
                            $scope.ShowTotalAppt.push(filterdate[0]);
                        }
                    });
                } else {
                    $scope.ShowTotalAppt = [];
                    angular.forEach($scope.Datecontainer, function (ditem) {
                        var obj = {
                            "AppointmentCount": "",
                            "AppointmentDate": ditem
                        };
                        $scope.ShowTotalAppt.push(obj);
                    });
                }

                console.log($scope.DataStoringArray);
                console.log($scope.ShowTotalAppt);
                $scope.AllDoctorsTotalAppointments = resp.data.AllDoctorsTotalAppointments;
                angular.forEach($scope.DataStoringArray, function (item) {
                    angular.forEach(item.AppointmentDatesList, function (Iitem) {
                        Iitem.IsShowThePrint = false;
                    })
                });

            }
        }, function (err) {
            console.log(err);
        });

    }
