    $scope.GetDataVisitReasonWiseAppt = function () {
        $scope.DataStoring = [];
        //console.log($scope.SelectDoctorForVisitApptID);
        //var DoctorIDForPrint = $scope.SelectDoctorForVisitApptID; 

        var checkedArrayList = [];
        if ($scope.sharedDoctors.MultiselectDoctorlist.length > 0) {
            checkedArrayList = _.where($scope.sharedDoctors.MultiselectDoctorlist, { isCheckedList: true });
        }
        var newlistForPrint = "";
        for (var i in $scope.MultiselectDoctorlist) {
            if ($scope.sharedDoctors.MultiselectDoctorlist[i].isCheckedList) {
                newlistForPrint += "," + $scope.sharedDoctors.MultiselectDoctorlist[i].DoctorID;
            }
        }
        if (newlistForPrint.charAt(0) === ",") {
            newlistForPrint = newlistForPrint.slice(1);
        }
        var newVisitlist = "";
        for (var i in $scope.VisitReasonsWiseApptCountForPrint) {
            if ($scope.VisitReasonsWiseApptCountForPrint[i].isChecked) {
                newVisitlist += "," + $scope.VisitReasonsWiseApptCountForPrint[i].ReasonId;
            }
        }
        if (newVisitlist.charAt(0) === ",") {
            newVisitlist = newVisitlist.slice(1);
        }
        var locationIds = $scope.AllApptBranchLocations
            .filter(pitem => pitem.IsChecked && pitem.ClinicId !== 0) // Exclude ClinicId === 0
            .map(pitem => pitem.ClinicId)
            .join(",");
        var obj = {
            "HospitalId": locationIds,//$scope.HospitalId
            "FromDate": $filter('date')(new Date($scope.SearchObj.ConsultationDtFromDate), "yyyy-MM-dd"),
            "ToDate": $filter('date')(new Date($scope.SearchObj.ConsultationDtTodate), "yyyy-MM-dd"),
            "DoctorIds": newlistForPrint || "",
            "VisitReasonIds": newVisitlist || "",
            "UserId": $scope.UserId || 0,
        };
        eHnotePatientDataService.GetApptCountAndPatientdataByVisitReason(obj).then(function (resp) {
            console.log(resp);
            if (resp.data.Status === 'Success') {
                $scope.VisitReasonWiseApptArray = resp.data.rows || [];
                $scope.VisitreasonByApptArray = angular.copy($scope.VisitReasonWiseApptArray);

                if ($scope.VisitreasonByApptArray.length > 0) {
                    angular.forEach($scope.VisitreasonByApptArray, function (aitem) {
                        angular.forEach(aitem.VisitReasons, function (subitem) {
                            subitem.VisitReasonwiseApptList = [];
                            subitem.VisitReasonDataList = [];
                            subitem.VisitReasonData = subitem.VisitReasonData || [];
                            subitem.VisitReasonWisePatietnArray = subitem.AppointmentsArray || [];

                            if (subitem.VisitReasonData.length > 0) {
                                angular.forEach($scope.Datecontainer, function (ditem) {
                                    var filtervisit = $filter('filter')(subitem.VisitReasonData, { 'AppointmentDate': ditem }, true) || [];
                                    if (filtervisit.length === 0) {
                                        var obj = {
                                            "AppointmentCount": "",
                                            "AppointmentDate": ditem,
                                        };
                                        subitem.VisitReasonwiseApptList.push(obj);
                                    } else {
                                        subitem.VisitReasonwiseApptList.push(filtervisit[0]);
                                    }
                                });
                            }
                            else {
                                angular.forEach($scope.Datecontainer, function (ditem) {
                                    var obj = {
                                        "AppointmentCount": "",
                                        "AppointmentDate": ditem
                                    };
                                    subitem.VisitReasonDataList.push(obj);
                                });
                            }
                        });
                        if (aitem.AppointmentDatesArray.length > 0) {
                            aitem.AppointmentDatesList = [];
                            angular.forEach($scope.Datecontainer, function (ditem) {
                                var filterdate = $filter('filter')(aitem.AppointmentDatesArray, { 'AppointmentDate': ditem }, true) || [];
                                if (filterdate.length === 0) {
                                    var obj = {
                                        "AppointmentCount": "",
                                        "AppointmentDate": ditem
                                    };
                                    aitem.AppointmentDatesList.push(obj);
                                } else {
                                    aitem.AppointmentDatesList.push(filterdate[0]);
                                }
                            });
                        } else {
                            aitem.AppointmentDatesList = [];
                            angular.forEach($scope.Datecontainer, function (ditem) {
                                var obj = {
                                    "AppointmentCount": "",
                                    "AppointmentDate": ditem
                                };
                                aitem.AppointmentDatesList.push(obj);
                            });
                        }

                    });
                }
                if ($scope.VisitreasonByApptArray.length > 0) {
                    angular.forEach($scope.VisitreasonByApptArray, function (data) {
                        angular.forEach(data.VisitReasons, function (subdata) {
                            angular.forEach(subdata.AppointmentsArray, function (Litem) {

                                Litem.shorttime = $filter('date')(new Date(Litem.ConsultationDt + " " + Litem.StartTime), "hh:mm a");
                                if (Litem.Patient.MobileNo.length > 0) {
                                    var obj = eHnoteUserDataService.UsMobileFormatChange(Litem.Patient.MobileNo);
                                    Litem.Patient.MobileNoUsFormate = obj.UsFormatMobileNumber;
                                }
                            });
                        });
                    });
                }


                angular.forEach($scope.VisitreasonByApptArray, function (item) {
                    angular.forEach(item.VisitReasons, function (Iitem) {
                        Iitem.IsShowVisitReasonPatient = false;
                    });
                });

            }
        }, function (err) {
            console.log(err);
        });

    }




