    $scope.FacilityTypeToggle = function () {
        var checkedArray = _.where($scope.FacilityList, { IsChecked: true });
        $scope.FacilityTypeObj.AllStatusCheck = checkedArray.length > 0 && $scope.FacilityList.length === checkedArray.length ? true : false;
        if ($scope.FacilityTypeObj.AllStatusCheck) {
            $scope.FacilityTypeObj.SelectStatusString = 'All';
        }

        if (!$scope.FacilityTypeObj.AllStatusCheck && checkedArray.length > 0) {
            $scope.FacilityTypeObj.SelectStatusString = 'Selected';
        }
    };
    $scope.GetAllUsers = function (id) {

        var subSplArray = _.pluck($scope.allSubSpecializationsArray, "SubSpecializationId").join(",");

        var HospitalId = 0;
        id = id || 0;
        if (id == 0) {
            var TempArray = $filter("filter")($scope.AppListdoctoraddress, function (iterator, ind) { return iterator.ClinicId !== 0; });
            var HospitalId = _.pluck(TempArray, "BranchId").join(",");
        } else {
            HospitalId = id;
        }

        var reqObj = {
            "BranchId": HospitalId || 0,
            "SubSpecializationIdArray": subSplArray
        }

        eHnoteMainAppointmentService.getAllUsersByDepartmentId(reqObj, onGetUsersSuccess, onGetUsersFailure);
        function onGetUsersSuccess(resp) {
            if (resp.rows.length > 0) {

                var UsersList = [];
                UsersList = resp.rows || [];
                if (UsersList.length > 0) {
                    $scope.MultiselectDoctorlist = [];
                    $scope.selectedDoctors = "Select Doctors";
                    angular.forEach(UsersList, function (Aitem) {
                        if (Aitem.RoleId === 1 || Aitem.RoleId === 43) {
                            Aitem.DoctorfullNamewithNPI = Aitem.SecondUserFullName + '-' + Aitem.NPI;
                            Aitem.isChecked = false;
                            if (doctorInfo.doctordata.User[0].DoctorID == Aitem.DoctorID) {
                                $scope.selectedDoctors = Aitem.SecondUserFullName + '-' + Aitem.NPI;
                                Aitem.isChecked = true;
                            }
                            $scope.MultiselectDoctorlist.push(Aitem);
                        }
                    });
                }
                $scope.MultiselectDoctorlist = _.uniq($scope.MultiselectDoctorlist, false, function (p) { return p.DoctorID; });

            } else {
                alertify.error("No Users Found in Selected Departments");
                $scope.MultiselectDoctorlist = [];

            }
        }

        function onGetUsersFailure(data) {
        }
    };
    $scope.GetParentOrgVisitReasons = function () {

        var params = {
            "ParentOrganizationId": $scope.ParenthospitalId || 0
        }
        eHnotePatientVisitReasonServices.GetParentOrgApptVisitReasons(params).then(function (resp) {

            if (resp.data.rows.length > 0) {
                $scope.Visitreasons = resp.data.rows || [];
                if ($scope.Visitreasons.length > 0) {
                    angular.forEach($scope.Visitreasons, function (item) {
                        item.isChecked = true;
                        item.ReasonId = item.ParentAppointmentVisitReasonId || 0;
                        item.Reason = item.AppointmentVisitReason || '';
                    });
                }

                $scope.AllDoctorsObj.AllVisitReasonsCheck = true;
                $scope.selectedVisitReason = 'All Visit Reasons';
            }
        })
    }

